{"content":"#include <stdio.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

static const uint8_t sbox[16] = {0xC,0x5,0x6,0xB,0x9,0x0,0xA,0xD,0x3,0xE,0xF,0x8,0x4,0x7,0x1,0x2};
static const uint8_t pbox[64] = {0,16,32,48,1,17,33,49,2,18,34,50,3,19,35,51,4,20,36,52,5,21,37,53,6,22,38,54,7,23,39,55,8,24,40,56,9,25,41,57,10,26,42,58,11,27,43,59,12,28,44,60,13,29,45,61,14,30,46,62,15,31,47,63};

static uint64_t T[4][65536];

static inline uint64_t rot1(uint64_t v){ return (v<<1)|(v>>15); }

void build_tables(){
    for(int c=0;c<4;c++){
        for(int v=0;v<65536;v++){
            uint64_t r=0;
            for(int i=0;i<4;i++){
                uint8_t nib=(v>>(i*4))&0xF;
                uint8_t sn=sbox[nib];
                for(int b=0;b<4;b++){
                    if((sn>>b)&1){
                        int srcbit=c*16+i*4+b;
                        r|=(1ULL<<pbox[srcbit]);
                    }
                }
            }
            T[c][v]=r;
        }
    }
}

static inline uint64_t encrypt_fast(uint64_t pt, uint64_t key){
    uint64_t s=pt, ck=key;
    for(int round=0;round<31;round++){
        s ^= (ck>>16);
        s = T[0][s&0xFFFF] ^ T[1][(s>>16)&0xFFFF] ^ T[2][(s>>32)&0xFFFF] ^ T[3][(s>>48)&0xFFFF];
        ck = rot1(ck);
    }
    s ^= (ck>>16);
    return s;
}

// reference slow for verification
static inline uint64_t apply_sbox_slow(uint64_t state) {
    uint64_t r=0;
    for(int i=0;i<16;i++){ uint8_t n=(state>>(i*4))&0xF; r|=((uint64_t)sbox[n])<<(i*4);}
    return r;
}
static inline uint64_t apply_pbox_slow(uint64_t state){
    uint64_t r=0;
    for(int i=0;i<64;i++){ r|=((state>>i)&1ULL)<<pbox[i];}
    return r;
}
static inline uint64_t encrypt_slow(uint64_t pt,uint64_t key){
    uint64_t s=pt,ck=key;
    for(int r=0;r<31;r++){ s^=(ck>>16); s=apply_sbox_slow(s); s=apply_pbox_slow(s); ck=rot1(ck);}
    s^=(ck>>16); return s;
}

int main(){
    build_tables();
    // verify
    uint64_t keys[]={REDACTED00000000000000000242ULL,0,1,0xFFFFFFFFFFFFFFFFULL,0x123456789ABCDEF0ULL};
    uint64_t pts[]={0,1,0xFFFFFFFFFFFFFFFFULL,0x0000000123456789ULL};
    for(int ki=0;ki<5;ki++) for(int pi=0;pi<4;pi++){
        uint64_t a=encrypt_fast(pts[pi],keys[ki]);
        uint64_t b=encrypt_slow(pts[pi],keys[ki]);
        if(a!=b){printf("MISMATCH k=%016llx p=%016llx fast=%016llx slow=%016llx\n",(unsigned long long)keys[ki],(unsigned long long)pts[pi],(unsigned long long)a,(unsigned long long)b);return 1;}
    }
    printf("tables ok\n");
    // benchmark
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    uint64_t acc=0;
    int N=2000000;
    for(int i=0;i<N;i++){ acc^=encrypt_fast(i,REDACTED00000000000000000242ULL);}
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("fast: %.2f Menc/s (acc=%llx)\n", N/dt/1e6, (unsigned long long)acc);
    return 0;
}
